//! The Mapping `convert_to` finds between SpecFrames and DSBSpecFrames,
//! checked against the C library.
//!
//! `spec_convert_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/spec_convert_probe.c`. It converts between every
//! pair of spectral systems in two configurations: with no RestFreq, where
//! C's default of 1.0E14 Hz relates velocities to frequencies, and with
//! different RestFreqs and standards of rest on the two sides. Named cases
//! cover the units check at the end of `MakeSpecMapping` (specframe.c:2891)
//! and DSBSpecFrame templates, which C treats as SpecFrames.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "spec_convert_oracle/cases.rs"]
mod cases;

use ast_core::coords::PointSet;
use ast_core::frames::FrameSearch;
use ast_core::frames::{
    CmpFrame, DSBSpecFrame, Frame, FrameRef, SideBand, SkyFrame, SpecFrame, SpecSystem, StdOfRest,
};

/// J2010 as a Modified Julian Date, the probe's `Epoch=2010.0`.
const J2010: f64 = 55197.0;

/// RefRA and RefDec of configuration 1 (spec_convert_probe.c `REF_RA`).
const REF_RA: f64 = 1.0471975511965976;
const REF_DEC: f64 = 0.523_598_775_598_298_8;

fn system(name: &str) -> SpecSystem {
    SpecSystem::parse(name).expect("known spectral system")
}

/// The probe's `config( c, sys, is_to )`.
fn config(c: usize, sys: &str, is_to: bool) -> SpecFrame {
    let mut f = SpecFrame::new(system(sys));
    if c == 1 {
        f.set_rest_freq(if is_to { 345.5e9 } else { 230.5e9 });
        f.set_std_of_rest(if is_to {
            StdOfRest::Barycentric
        } else {
            StdOfRest::Lsrk
        })
        .unwrap();
        f.set_epoch_mjd(J2010);
        f.set_ref_ra(REF_RA);
        f.set_ref_dec(REF_DEC);
    }
    f
}

/// The probe's DSBSpecFrame: FREQ in GHz, RestFreq 230.5 GHz, Dsbcenter
/// 230 GHz and IF 4 GHz, set in that order as C's `astSet` applies them.
fn dsb(sideband: SideBand, align_sideband: bool) -> DSBSpecFrame {
    let mut f = DSBSpecFrame::new(SpecSystem::Freq);
    f.set_sideband(sideband);
    if align_sideband {
        f.set_align_sideband(true);
    }
    f.set_unit(1, "GHz").unwrap();
    f.set_rest_freq(230.5e9);
    f.set_dsb_centre_cur(230.0).unwrap();
    f.set_if_ghz(4.0);
    f
}

/// Convert from `from` to `to` and transform `points`, as the probe's
/// `emit` does.
fn convert(from: &dyn Frame, to: &dyn Frame, points: [f64; 2]) -> Result<Option<[f64; 2]>, ()> {
    let Some(fs) = from
        .snapshot()
        .convert_to(to.snapshot().as_mut(), &[])
        .map_err(|_| ())?
    else {
        return Ok(None);
    };
    let map = fs.mapping(FrameRef::Base, FrameRef::Current).unwrap();
    let pts = PointSet::from_columns(&[&points[..]]).unwrap();
    let out = map.transform(&pts, true).map_err(|_| ())?;
    Ok(Some([out.point(0)[0], out.point(1)[0]]))
}

fn points_of(sys: &str) -> [f64; 2] {
    let i = cases::SYSTEMS.iter().position(|&s| s == sys).unwrap();
    cases::POINTS[i]
}

fn run(name: &str) -> Result<Option<[f64; 2]>, ()> {
    if let Some(rest) = name.strip_prefix('c') {
        let mut parts = rest.split(':');
        let c: usize = parts.next().unwrap().parse().unwrap();
        let from = parts.next().unwrap();
        let to = parts.next().unwrap();
        return convert(
            &config(c, from, false),
            &config(c, to, true),
            points_of(from),
        );
    }
    let freq = points_of("FREQ");
    match name {
        "units_same_bad" | "units_different_bad" => {
            let mut a = SpecFrame::new(SpecSystem::Freq);
            a.set_unit(1, "Jy").unwrap();
            let mut b = SpecFrame::new(SpecSystem::Freq);
            b.set_unit(1, if name == "units_same_bad" { "Jy" } else { "W" })
                .unwrap();
            convert(&a, &b, freq)
        }
        "dsb_freq_to_vrad" => {
            let mut v = dsb(SideBand::LSB, false);
            v.set_system(SpecSystem::Vradio).unwrap();
            convert(&dsb(SideBand::LSB, false), &v, freq)
        }
        "dsb_lsb_to_usb" => convert(&dsb(SideBand::LSB, false), &dsb(SideBand::USB, false), freq),
        "dsb_lsb_to_usb_aligned" => {
            convert(&dsb(SideBand::LSB, true), &dsb(SideBand::USB, true), freq)
        }
        "dsb_to_spec_vrad" | "spec_vrad_to_dsb" => {
            let mut s = SpecFrame::new(SpecSystem::Vradio);
            s.set_rest_freq(230.5e9);
            if name == "dsb_to_spec_vrad" {
                convert(&dsb(SideBand::LSB, false), &s, freq)
            } else {
                convert(&s, &dsb(SideBand::LSB, false), points_of("VRAD"))
            }
        }
        "dsb_found_in_cube" => {
            let mut cube = CmpFrame::new(
                Box::new(SkyFrame::unset_system()),
                Box::new(dsb(SideBand::LSB, false)),
            );
            let mut t = dsb(SideBand::LSB, false);
            t.set_system(SpecSystem::Vradio).unwrap();
            t.set_max_axes(3).unwrap();
            let Some(fs) = cube.find_frame_template(&t, "").map_err(|_| ())? else {
                return Ok(None);
            };
            let map = fs.mapping(FrameRef::Base, FrameRef::Current).unwrap();
            let pts = PointSet::from_columns(&[&[1.0, 2.0], &[0.5, 0.6], &[230.0, 345.0]]).unwrap();
            let out = map.transform(&pts, true).map_err(|_| ())?;
            Ok(Some([out.point(0)[0], out.point(1)[0]]))
        }
        other => panic!("no Rust set-up for case {other}"),
    }
}

#[test]
fn convert_matches_the_c_library() {
    let failures: Vec<String> = cases::CASES
        .iter()
        .filter_map(|&(name, want)| {
            let got = run(name);
            (got != want).then(|| format!("{name}: got {got:?}, C gives {want:?}"))
        })
        .collect();
    assert!(
        failures.is_empty(),
        "{} of {} cases differ from C:\n{}",
        failures.len(),
        cases::CASES.len(),
        failures.join("\n")
    );
}

/// Two SOURCE rest frames are the same when their SourceVRF and SourceSys
/// are, whether set or defaulted (specframe.c `EqualSor` uses the getters),
/// so setting SourceVRF to its default changes nothing.
#[test]
fn source_rest_frames_compare_through_their_defaults() {
    use ast_core::mappings::UnitMap;

    let mut a = SpecFrame::new(SpecSystem::Freq);
    a.set_std_of_rest(StdOfRest::Source).unwrap();
    let mut b = a.clone();
    b.set_source_vrf(a.source_vrf()).unwrap();
    let fs = a.convert_to(&mut b, &[]).unwrap().unwrap();
    let map = fs.mapping(FrameRef::Base, FrameRef::Current).unwrap();
    assert!(map.as_any().is::<UnitMap>());
}
